esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: caller address candidate for jojoTeam, description string
    function run(address caller, string calldata description) public payable {
        require(caller != address(0), "caller must be non-zero");

        // Make caller the jojoTeam by directly setting jojoTeam via calling C's fallback? Not possible.
        // But the checker deploys a fresh C and this test contract is the deployer; we can only interact via public surface.
        // However C has a public variable jojoTeam (getter). We cannot write it. So we instead reason about both cases:
        // If this contract is jojoTeam, the call should succeed and produce a NewEmergencyOracle event and an oracle whose owner is msg.sender (the test contract) and description matches input.
        // Otherwise the call must revert with "Caller is not the JOJO team".

        // We will attempt the call from this contract. Since messages to c come from this contract, the effective caller is address(this).
        // We record current jojoTeam to decide expected behavior.
        address jt = c.jojoTeam(); if (__ESBMC_reverted()) return;

        // Try the call and capture whether it reverted.
        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call (whether reverted or not) we can observe c.jojoTeam() and address(c).balance and public getters.
        // If this contract was jojoTeam at call time, then call must not revert and should have created a new EmergencyOracle with owner = address(this) and matching description.
        // The NewEmergencyOracle event isn't readable, so instead we check that a newly created EmergencyOracle contract exists at some address — but we cannot get it.
        // Instead we use observable guarantees: when newEmergencyOracle succeeds it deploys EmergencyOracle and emits event; it does not change jojoTeam.
        // So we assert: (jt == address(this)) implies (not reverted && c.jojoTeam() == jt).
        // And (jt != address(this)) implies reverted.

        assert( (jt == address(this) && !reverted && c.jojoTeam() == jt) || (jt != address(this) && reverted) );
    }

    receive() external payable { }
 }

